'use strict';
const assert = require('node:assert');
const api = require('./solution');

assert.strictEqual(Reflect.ownKeys(api).length, 1);
assert.strictEqual(typeof api.viewportProgress, 'function');
const { viewportProgress } = api;
const typeError = (fn) => assert.throws(fn, TypeError);

assert.deepStrictEqual(
  viewportProgress({ offset: 0, viewportSize: 200, contentSize: 1000 }),
  { ratio: 0, atEnd: false }
);
assert.deepStrictEqual(
  viewportProgress({ offset: 400, viewportSize: 200, contentSize: 1000 }),
  { ratio: 0.5, atEnd: false }
);
assert.deepStrictEqual(
  viewportProgress({ offset: 800, viewportSize: 200, contentSize: 1000 }),
  { ratio: 1, atEnd: true }
);
assert.deepStrictEqual(
  viewportProgress({ offset: 5000, viewportSize: 200, contentSize: 1000 }),
  { ratio: 1, atEnd: true }
);
assert.deepStrictEqual(
  viewportProgress({ offset: 50, viewportSize: 100, contentSize: 100 }),
  { ratio: 1, atEnd: true }
);
assert.deepStrictEqual(
  viewportProgress({ offset: 0, viewportSize: 200, contentSize: 100 }),
  { ratio: 1, atEnd: true }
);
assert.deepStrictEqual(
  viewportProgress({ offset: 0, viewportSize: 0, contentSize: 0 }),
  { ratio: 1, atEnd: true }
);

const metrics = { offset: 25, viewportSize: 50, contentSize: 150, ignored: 'x' };
const result = viewportProgress(metrics);
assert.deepStrictEqual(result, { ratio: 0.25, atEnd: false });
assert.deepStrictEqual(metrics, { offset: 25, viewportSize: 50, contentSize: 150, ignored: 'x' });
assert.notStrictEqual(result, metrics);

const nullPrototypeMetrics = Object.create(null);
nullPrototypeMetrics.offset = 1;
nullPrototypeMetrics.viewportSize = 1;
nullPrototypeMetrics.contentSize = 2;
assert.deepStrictEqual(viewportProgress(nullPrototypeMetrics), { ratio: 1, atEnd: true });

for (const invalid of [null, [], new Date(), 'metrics', Object.create({})]) {
  typeError(() => viewportProgress(invalid));
}
for (const invalid of [
  { offset: -1, viewportSize: 1, contentSize: 2 },
  { offset: 0, viewportSize: -1, contentSize: 2 },
  { offset: 0, viewportSize: 1, contentSize: -2 },
  { offset: NaN, viewportSize: 1, contentSize: 2 },
  { offset: Infinity, viewportSize: 1, contentSize: 2 },
  { offset: 0, viewportSize: '1', contentSize: 2 },
  { offset: 0, viewportSize: 1 }
]) {
  typeError(() => viewportProgress(invalid));
}

